#!/bin/bash
set -e
# Jarvis acilis sesi: ses dosyasini uygulamaya ekler (depo klasorunde calistir)
D=app/src/main/java/com/batuhan/jarvis
F=$D/MainActivity.kt
[ -f "$F" ] || { echo "Hata: bu betigi jarvis depo klasorunun icinde calistir"; exit 1; }

mkdir -p app/src/main/res/raw
base64 -d > app/src/main/res/raw/jarvis_voice.mp3 << 'AUDIO'

AUDIO

cat > $D/IntroPlayer.kt << 'KT'
package com.batuhan.jarvis

import android.content.Context
import android.media.MediaPlayer

object IntroPlayer {
    private var mp: MediaPlayer? = null

    fun play(context: Context, onEnd: () -> Unit) {
        try {
            mp?.release()
            val p = MediaPlayer.create(context, R.raw.jarvis_voice)
            if (p == null) { onEnd(); return }
            mp = p
            p.setOnCompletionListener { it.release(); mp = null; onEnd() }
            p.start()
        } catch (e: Exception) {
            onEnd()
        }
    }

    fun release() {
        try { mp?.release() } catch (e: Exception) {}
        mp = null
    }
}
KT

# MainActivity: playIntro fonksiyonu (onDestroy'dan once)
sed -i '/override fun onDestroy() {/i\    private fun playIntro() {\n        speaking = true; stateView.text = "KONUŞUYOR"; ui.post(speakAnim)\n        IntroPlayer.play(this) { speaking = false; orb.setLevel(0f); stateView.text = "SESSİZ" }\n    }\n' "$F"
# Acilista Jarvis modundaysa calsin
sed -i 's/^        ensurePermission()$/        ensurePermission()\n        if (!ultron) ui.postDelayed({ playIntro() }, 700)/' "$F"
# Ultron'dan Jarvis'e donunce calsin
sed -i 's/say(if (ultron) "Ultron devrede." else "Jarvis geri dondu efendim.")/if (ultron) say("Ultron devrede.") else playIntro()/' "$F"
# Kapanirken serbest birak
sed -i 's/^        tts?.shutdown()$/        tts?.shutdown()\n        IntroPlayer.release()/' "$F"

grep -c "playIntro" "$F"
git add -A
git commit -m "Jarvis acilis sesi eklendi

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>
Claude-Session: https://claude.ai/code/session_01HNepVBtT3Pq93zy5cRDNbn"
git push
